/* The GL command queue: a render thread for the port's GL calls.
 *
 * Include after the GL headers in every translation unit that calls GL. Each
 * GL entry point becomes a macro (pc_glq_gen.h, generated by tools/gen_glq.py)
 * that runs the call directly while the render thread is off, and otherwise
 * queues it for the render thread, which owns the context. See pc_glq.c. */
#ifndef PC_GLQ_H
#define PC_GLQ_H

#include <stddef.h>
#include <string.h>

/* 1 while the render thread owns the context. Set and cleared by the game
 * thread only; the render thread never reads it. */
extern int pc_glq_active;
extern int pc_glq_sync_all; /* MELEE_GLQ_SYNC_ALL: a diagnostic */

void* pc_glq_push(void (*fn)(void*), size_t bytes);
void pc_glq_commit(void);
void pc_glq_call_sync(void (*fn)(void*), void* args);
size_t pc_glq_pixel_bytes(int width, int height, unsigned format, unsigned type);
static inline size_t pc_glq_pad(size_t n) { return (n + 15) & ~(size_t) 15; }

/* Hand the context to a render thread (MELEE_GL_THREAD=1) -- called from the
 * first present, when the port's own start-up GL is done. */
void pc_glq_maybe_start(void* sdl_window, void* gl_context);
/* Queue the present; waits while the render thread is a frame behind. */
void pc_glq_swap(void* sdl_window);
int pc_glq_set_swap_interval(int interval);
/* Run everything queued, then return. */
void pc_glq_drain(void);
void pc_glq_wait_report(unsigned frames);

/* Crash breadcrumb (main.c prints it) and MELEE_GLTIME. */
extern const char* volatile pc_gl_crumb_fn;
extern volatile int pc_gl_crumb_line;
extern volatile unsigned pc_gl_crumb_n;
extern volatile long pc_gl_crumb_arg[6];
extern volatile unsigned pc_gl_crumb_prog, pc_gl_crumb_fbo;
extern volatile long pc_gl_crumb_tex[4], pc_gl_crumb_texp[4];
extern int pc_gltime_on;
int pc_gltime_init(void);
void pc_gltime_begin(void);
void pc_gltime_add(const char* name);
void pc_gltime_report(unsigned frames);
static inline int pc_gltime_enabled(void) { return pc_gltime_on > 0 || (pc_gltime_on < 0 && pc_gltime_init()); }

extern void* pc_gllog_fp; /* MELEE_GLLOG=<path>: every GL call, name and line */
void pc_gllog(const char* fn, int line);
#define PC_GLC(fn) (pc_gl_crumb_fn = fn, pc_gl_crumb_line = __LINE__, pc_gl_crumb_n++, pc_gllog_fp ? pc_gllog(fn, __LINE__) : (void) 0)
#define PCQ_V(name, call) (PC_GLC(name), pc_gltime_enabled() ? (pc_gltime_begin(), (call), pc_gltime_add(name)) : (void) (call))
#define PCQ_R(name, call) (PC_GLC(name), ({ __typeof__(call) pcq_r_; if (pc_gltime_enabled()) { pc_gltime_begin(); pcq_r_ = (call); pc_gltime_add(name); } else pcq_r_ = (call); pcq_r_; }))

/* State the game thread tracks as it queues, so the per-frame queries are
 * answered without waiting on the render thread. */
/* What "framebuffer 0" binds: the window, or the scene framebuffer of an
 * internal render resolution (gx_gl_bridge.c, pc_ires_*). */
extern GLuint pc_glq_default_fb;
static inline GLuint pc_glq_map_fb(GLuint fb) { return fb == 0 ? pc_glq_default_fb : fb; }
void pc_glq_shadow_glUseProgram(GLuint program);
void pc_glq_shadow_glBindFramebuffer(GLenum target, GLuint fb);
void pc_glq_shadow_glViewport(GLint x, GLint y, GLsizei w, GLsizei h);
void pc_glq_shadow_glScissor(GLint x, GLint y, GLsizei w, GLsizei h);
void pc_glq_shadow_glActiveTexture(GLenum unit);
void pc_glq_shadow_glBindTexture(GLenum target, GLuint tex);
void pc_glq_shadow_glBindVertexArray(GLuint vao);
void pc_glq_shadow_glBindBuffer(GLenum target, GLuint buf);
void pc_glq_shadow_glPixelStorei(GLenum pname, GLint param);

/* Handled by hand: fences become handles the render thread fills and polls,
 * and glGetIntegerv answers from the shadow where it can. */
GLsync pcq_glFenceSync(GLenum condition, GLbitfield flags);
GLenum pcq_glClientWaitSync(GLsync sync, GLbitfield flags, GLuint64 timeout);
void pcq_glDeleteSync(GLsync sync);
void pcq_glGetIntegerv(GLenum pname, GLint* data);
#define glFenceSync(...) PCQ_R("glFenceSync", pcq_glFenceSync(__VA_ARGS__))
#define glClientWaitSync(...) PCQ_R("glClientWaitSync", pcq_glClientWaitSync(__VA_ARGS__))
#define glDeleteSync(...) PCQ_V("glDeleteSync", pcq_glDeleteSync(__VA_ARGS__))
#define glGetIntegerv(...) PCQ_V("glGetIntegerv", pcq_glGetIntegerv(__VA_ARGS__))

#include "pc_glq_gen.h"

#endif
